'use strict'

const fs = require('node:fs')

const MAX_HISTORY = 3

/**
 * Posts or updates the AILF score report comment on a pull request.
 *
 * Loaded from `actions/github-script` via `require()` so filesystem access uses
 * Node's native `require` (not the action's wrapped one). github-script v9
 * injects `getOctokit` into the inline script scope and `@actions/github` is
 * ESM-only, so this module must not redeclare `getOctokit` or require that
 * package.
 *
 * @param {{github: object, context: object}} args
 * `github` is the octokit client from github-script (`paginate` + `rest.issues`).
 * `context` is the workflow run context (`issue`, `payload`, `repo`).
 */
async function postAilfPrComment({github, context}) {
  const pluginKey = process.env.PLUGIN_KEY
  const pluginPath = process.env.PLUGIN_PATH
  const workflowRunUrl = process.env.WORKFLOW_RUN_URL
  const MARKER = `<!-- ailf-score-report-${pluginKey} -->`
  const HISTORY_START = `<!-- ailf-score-history-${pluginKey} -->`
  const HISTORY_END = `<!-- /ailf-score-history-${pluginKey} -->`
  const ENTRY_MARKER = `<!-- ailf-score-entry-${pluginKey} -->`

  let newReport
  try {
    newReport = fs.readFileSync(`/tmp/ailf-report-${pluginKey}.md`, 'utf-8')
  } catch {
    newReport = `## AI Literacy Evaluation - \`${pluginPath}\`\n\nNo report generated. Check the [workflow logs](${workflowRunUrl}).`
  }

  const prNumber = context.issue?.number || context.payload?.pull_request?.number
  if (!prNumber) {
    console.log('No PR number found, skipping comment')
    return
  }

  const comments = await github.paginate(github.rest.issues.listComments, {
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: prNumber,
    per_page: 100,
  })
  const existing = comments.find((c) => c.body?.includes(MARKER))

  let historyEntries = []
  if (existing) {
    const oldBody = existing.body || ''
    const histStart = oldBody.indexOf(HISTORY_START)
    const histEnd = oldBody.indexOf(HISTORY_END)
    if (histStart !== -1 && histEnd !== -1) {
      const historyContent = oldBody.slice(histStart + HISTORY_START.length, histEnd).trim()
      if (historyContent) {
        historyEntries = historyContent
          .split(ENTRY_MARKER)
          .map((entry) => entry.trim())
          .filter(Boolean)
      }
    }

    let previousReport = ''
    if (histStart !== -1) {
      const markerIdx = oldBody.indexOf(MARKER)
      const separatorIdx = oldBody.lastIndexOf('---', histStart)
      const endIdx = separatorIdx > markerIdx ? separatorIdx : histStart
      previousReport = oldBody.slice(markerIdx + MARKER.length, endIdx).trim()
    } else {
      const markerIdx = oldBody.indexOf(MARKER)
      if (markerIdx !== -1) {
        previousReport = oldBody.slice(markerIdx + MARKER.length).trim()
      }
    }

    if (previousReport) {
      const scoreMatch = previousReport.match(/Overall:\s*(\d+)\/100/)
      const score = scoreMatch ? scoreMatch[1] : '?'
      const dateMatch = previousReport.match(/Generated by.*?·\s*([^·<\n*]+)/)
      const date = dateMatch
        ? dateMatch[1].trim()
        : new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC'
      const entry = `<details>\n<summary>${date} - ${score}/100</summary>\n\n${previousReport}\n\n</details>`
      historyEntries.unshift(entry)
    }

    historyEntries = historyEntries.slice(0, MAX_HISTORY)
  }

  const historySection =
    historyEntries.length > 0
      ? `\n\n---\n\n### Previous runs\n\n${HISTORY_START}\n${historyEntries.map((entry) => `${ENTRY_MARKER}\n${entry}`).join('\n\n')}\n${HISTORY_END}`
      : ''
  const finalBody = `${MARKER}\n${newReport}${historySection}`

  if (existing) {
    await github.rest.issues.updateComment({
      owner: context.repo.owner,
      repo: context.repo.repo,
      comment_id: existing.id,
      body: finalBody,
    })
    console.log(`Updated comment for ${pluginKey} (${historyEntries.length} history entries)`)
  } else {
    await github.rest.issues.createComment({
      owner: context.repo.owner,
      repo: context.repo.repo,
      issue_number: prNumber,
      body: finalBody,
    })
    console.log(`Created new PR comment for ${pluginKey}`)
  }
}

module.exports = {postAilfPrComment}
